const input = tobub.params || {};
const authorNameInput = String(input.authorName ?? '').trim();
const authorIdInput = String(input.authorId ?? '').trim();
const maxWorks = Number(input.maxWorks ?? 50);
if (!authorNameInput) throw new Error('请填写作者名称或小红书号；如有同名账号，可补充作者主页 ID 或链接。');
if (!Number.isInteger(maxWorks) || maxWorks < 1 || maxWorks > 500) {
  throw new Error('最大作品数必须是 1 到 500 的整数。');
}

function normalizeAuthorId(value) {
  const looksLikeUrl = /^[a-z][a-z0-9+.-]*:\/\//i.test(value)
    || /(^|\/)(www\.)?xiaohongshu\.com\//i.test(value);
  if (!looksLikeUrl) {
    const id = value.replace(/^@/, '');
    if (!/^[A-Za-z0-9_-]{6,80}$/.test(id)) {
      throw new Error('作者 ID 格式无效；请填写小红书作者主页链接或主页 ID。');
    }
    return id;
  }
  let url;
  try {
    url = new URL(/^[a-z][a-z0-9+.-]*:\/\//i.test(value) ? value : 'https://' + value);
  } catch {
    throw new Error('作者主页链接无效。');
  }
  const host = url.hostname.toLowerCase();
  if (!['xiaohongshu.com', 'www.xiaohongshu.com'].includes(host)) {
    throw new Error('作者主页链接必须来自 xiaohongshu.com。');
  }
  if (!['http:', 'https:'].includes(url.protocol)) {
    throw new Error('作者主页链接必须使用 HTTP 或 HTTPS。');
  }
  let path = url.pathname;
  try { path = decodeURIComponent(path); } catch {}
  const match = path.match(/^\/user\/profile\/([^/]+)\/?$/i);
  if (!match) {
    throw new Error('请复制作者主页链接，格式应为 xiaohongshu.com/user/profile/作者ID。');
  }
  return match[1];
}

const expectedAuthorId = authorIdInput ? normalizeAuthorId(authorIdInput) : '';
let authorId = expectedAuthorId;
let profileUrl = expectedAuthorId
  ? 'https://www.xiaohongshu.com/user/profile/' + encodeURIComponent(expectedAuthorId)
  : 'https://www.xiaohongshu.com/explore';
const maxScrollPasses = 120;
const seen = new Set();
const works = [];
let authorName = authorNameInput;
let xiaohongshuId = /^\d{6,20}$/.test(authorNameInput) ? authorNameInput : '';
let candidateAuthors = [];
let authorContentItemId = null;
let authorSaveAttempted = false;
let cardsSeen = 0;
let duplicateCount = 0;
let malformedCount = 0;
let extractionFailures = 0;
let saveFailures = 0;
let scrolls = 0;
let stopReason = 'search_failed';
let error = '';
let terminalSeen = false;
let probe = null;
let authorIdentityVerified = false;

function unwrap(value) {
  if (value && value.value !== undefined) return value.value;
  if (value && value.result !== undefined) return value.result;
  return value;
}
function safeText(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}
function getNoteId(value) {
  try {
    const parts = new URL(String(value), 'https://www.xiaohongshu.com').pathname.split('/').filter(Boolean);
    const exploreIndex = parts.indexOf('explore');
    if (exploreIndex >= 0 && parts[exploreIndex + 1]) return parts[exploreIndex + 1];
    const discoveryIndex = parts.indexOf('discovery');
    if (discoveryIndex >= 0 && parts[discoveryIndex + 1] === 'item' && parts[discoveryIndex + 2]) {
      return parts[discoveryIndex + 2];
    }
  } catch {}
  return '';
}
function normalizeSiteUrl(value, fallbackId) {
  const raw = String(value ?? '').trim();
  if (!raw && fallbackId) return 'https://www.xiaohongshu.com/explore/' + encodeURIComponent(fallbackId);
  try {
    const url = new URL(raw, 'https://www.xiaohongshu.com');
    if (!['xiaohongshu.com', 'www.xiaohongshu.com'].includes(url.hostname.toLowerCase())) return '';
    return url.href;
  } catch {
    return fallbackId ? 'https://www.xiaohongshu.com/explore/' + encodeURIComponent(fallbackId) : '';
  }
}

const probeExpression = [
  '(()=>{',
  'const body=(document.body&&document.body.innerText)||"";',
  'const candidates=["div.feeds-container > section.note-item","section.note-item","div.feeds-container section","div.note-item","[data-note-id]"];',
  'const ranked=candidates.map(selector=>{',
  'let nodes=[];try{nodes=Array.from(document.querySelectorAll(selector));}catch{}',
  'let score=0;',
  'for(const node of nodes.slice(0,8)){',
  'const links=Array.from(node.querySelectorAll("a[href]"));',
  'if(links.some(a=>/\\/(?:explore|discovery\\/item)\\//.test(a.getAttribute("href")||"")))score+=8;',
  'if(node.querySelector("img"))score+=2;',
  'if(String(node.innerText||"").trim().length>2)score+=1;',
  '}',
  'return{selector,count:nodes.length,score};',
  '}).filter(x=>x.count>0).sort((a,b)=>b.score-a.score||b.count-a.count);',
  'const itemSelector=ranked.length?ranked[0].selector:"";',
  'const cards=itemSelector?Array.from(document.querySelectorAll(itemSelector)).slice(0,8):[];',
  'function choose(selectors,predicate){for(const selector of selectors){for(const card of cards){let el=null;try{el=card.querySelector(selector);}catch{}if(el&&predicate(el))return selector;}}return"";}',
  'const linkSelector=choose(["a[href*=\\\"/explore/\\\"]","a[href*=\\\"/discovery/item/\\\"]","a[href*=\\\"/note/\\\"]"],el=>/\\/(?:explore|discovery\\/item)\\//.test(el.getAttribute("href")||""));',
  'const titleSelector=choose(["div.footer a.title","a.title","a[href*=\\\"/explore/\\\"]","a[href*=\\\"/discovery/item/\\\"]","[class*=\\\"title\\\"]"],el=>String(el.innerText||el.textContent||"").trim().length>0)||linkSelector;',
  'const timeSelector=choose(["time",".name-time-wrapper .time","[class*=\\\"time\\\"]","[class*=\\\"date\\\"]"],el=>String(el.innerText||el.getAttribute("datetime")||"").trim().length>0);',
  'const likeSelector=choose(["span.like-wrapper span.count","[class*=\\\"like\\\"] .count","[class*=\\\"like\\\"]"],el=>String(el.innerText||el.getAttribute("aria-label")||"").trim().length>0);',
  'const coverSelector=choose(["img"],el=>Boolean(el.getAttribute("src")||el.getAttribute("data-src")||el.getAttribute("data-original")));',
  'const idAttrs=["data-note-id","data-id","note-id"];',
  'const idAttr=idAttrs.find(attr=>cards.some(card=>card.getAttribute(attr)))||"";',
  'const coverEl=coverSelector&&cards.length?cards.map(card=>card.querySelector(coverSelector)).find(Boolean):null;',
  'const coverAttr=coverEl?(coverEl.getAttribute("data-src")?"data-src":coverEl.getAttribute("data-original")?"data-original":"src"):"";',
  'const timeEl=timeSelector&&cards.length?cards.map(card=>card.querySelector(timeSelector)).find(Boolean):null;',
  'const timeAttr=timeEl&&timeEl.getAttribute("datetime")?"datetime":"";',
  'const nameSelectors=["div.user-info h1","div.user-info h2","[class*=\\\"nickname\\\"]","[class*=\\\"nick-name\\\"]","[class*=\\\"user-name\\\"]","h1","h2"];',
  'let profileName="";',
  'for(const selector of nameSelectors){let el=null;try{el=document.querySelector(selector);}catch{}const text=String(el&&(el.innerText||el.textContent)||"").replace(/\\s+/g," ").trim();if(text&&text.length<=60&&!/关注|粉丝|获赞/.test(text)){profileName=text;break;}}',
  'const pathId=(location.pathname.match(/\\/user\\/profile\\/([^/]+)/)||[])[1]||"";',
  'const xiaohongshuId=(body.match(/小红书号\\s*[:：]?\\s*([A-Za-z0-9_-]+)/)||[])[1]||"";',
  'const endSignal=/暂时没有更多|没有更多了|没有更多作品|已经到底了|暂无笔记|暂无作品/.test(body);',
  'const loginGate=/扫码登录|登录后查看更多|请先登录|登录后查看/.test(body);',
  'return{url:location.href,pathname:location.pathname,profileId:pathId,profileName,xiaohongshuId,itemSelector,cardCount:itemSelector?document.querySelectorAll(itemSelector).length:0,selectorCounts:ranked,selectors:{link:linkSelector,title:titleSelector,time:timeSelector,like:likeSelector,cover:coverSelector,idAttr,coverAttr,timeAttr},endSignal,loginGate,bodyText:body.slice(0,2400)};',
  '})()'
].join('');

const searchProbeExpression = [
  '(()=>{',
  'const body=(document.body&&document.body.innerText)||"";',
  'const tab=document.querySelector("#user");',
  'const anchors=Array.from(document.querySelectorAll("a[href*=\\\"/user/profile/\\\"]")).filter(a=>a.querySelector(".user-item-box")&&a.querySelector(".user-name"));',
  'const candidates=anchors.map(a=>{',
  'const rawHref=a.getAttribute("href")||"";',
  'let id="",url="";try{const u=new URL(rawHref,location.origin);url=u.href;id=(u.pathname.match(/\\/user\\/profile\\/([^/]+)/)||[])[1]||"";}catch{}',
  'const name=String(a.querySelector(".user-name")?.innerText||a.querySelector(".user-name")?.textContent||"").replace(/\\s+/g," ").trim();',
  'const text=String(a.innerText||a.textContent||"").replace(/\\s+/g," ").trim();',
  'const xiaohongshuId=(text.match(/小红书号\\s*[:：]?\\s*([A-Za-z0-9_-]+)/)||[])[1]||"";',
  'return{id,name,xiaohongshuId,url,href:rawHref,text};',
  '}).filter(x=>x.id&&x.name);',
  'const unique=new Map();for(const item of candidates){if(!unique.has(item.id))unique.set(item.id,item);}',
  'return{url:location.href,pathname:location.pathname,isSearchPage:/^\\/search_result/.test(location.pathname),hasUserTab:Boolean(tab),userTabActive:Boolean(tab&&tab.querySelector(".channel-content.active")),candidates:Array.from(unique.values()).slice(0,30),bodyText:body.slice(0,2000)};',
  '})()'
].join('');

async function observePage() {
  return unwrap(await tobub.atoms.evaluate({ mode: 'expression', expression: probeExpression }));
}
async function observeSearchPage() {
  return unwrap(await tobub.atoms.evaluate({ mode: 'expression', expression: searchProbeExpression }));
}
async function ensureAuthorRecord() {
  if (authorSaveAttempted) return;
  authorSaveAttempted = true;
  try {
    const saved = await tobub.db.saveContent({
      platform: 'xiaohongshu',
      contentType: 'user',
      externalId: authorId,
      title: authorName || authorId,
      summary: '',
      url: profileUrl,
      metadata: { authorId, authorName, xiaohongshuId, source: 'author_profile', capturedAt: new Date().toISOString() },
      rawData: { authorId, authorName, xiaohongshuId, profileUrl }
    });
    const id = Number(saved?.contentItemId);
    if (Number.isInteger(id) && id > 0) authorContentItemId = id;
    else saveFailures++;
  } catch {
    saveFailures++;
  }
}
function makeFields(currentProbe) {
  const selectors = currentProbe?.selectors ?? {};
  const fields = [];
  if (selectors.idAttr) fields.push({ name: 'id', source: { attr: selectors.idAttr } });
  if (selectors.link) {
    fields.push({ name: 'link', selector: selectors.link, source: 'href', transforms: [{ type: 'absoluteUrl', baseUrl: 'https://www.xiaohongshu.com' }] });
  }
  if (selectors.title) fields.push({ name: 'title', selector: selectors.title, source: 'text', transforms: [{ type: 'normalizeWhitespace' }], fallback: '' });
  if (selectors.cover && selectors.coverAttr) fields.push({ name: 'cover', selector: selectors.cover, source: { attr: selectors.coverAttr }, fallback: '' });
  if (selectors.time) {
    fields.push({
      name: 'publishedAt',
      selector: selectors.time,
      source: selectors.timeAttr ? { attr: selectors.timeAttr } : 'text',
      fallback: ''
    });
  }
  if (selectors.like) fields.push({ name: 'likes', selector: selectors.like, source: 'text', fallback: '' });
  return fields;
}

try {
  await tobub.atoms.navigate({ url: 'https://www.xiaohongshu.com/explore', waitUntil: 'domcontentloaded' });
  await tobub.atoms.waitFor({ delay: [1200, 1800] });
  const homeProbe = await observeSearchPage();
  if (!homeProbe?.pathname?.startsWith('/explore') || !homeProbe?.url?.includes('xiaohongshu.com')) {
    stopReason = 'search_failed';
    error = '无法从小红书首页开始搜索作者。';
    throw new Error(error);
  }

  const searchBoxReady = await tobub.atoms.condition({
    type: 'visible',
    selector: '#search-input-in-feeds',
    pollInterval: 200,
    throwOnTimeout: false
  }, { timeout: 10000 });
  if (!searchBoxReady?.satisfied) {
    const pageState = await observeSearchPage();
    stopReason = 'search_failed';
    error = '小红书首页搜索框未在 10 秒内显示；当前页面：' + safeText(pageState?.pathname || '未知');
    throw new Error(error);
  }
  await tobub.atoms.fill(
    { selector: '#search-input-in-feeds', value: authorNameInput, verify: true },
    { timeout: 10000 }
  );
  await tobub.atoms.press({ selector: '#search-input-in-feeds', key: 'Enter' }, { timeout: 10000 });
  await tobub.atoms.waitFor({ delay: [1500, 2200] });
  let searchProbe = await observeSearchPage();
  for (let attempt = 0; attempt < 3 && (!searchProbe?.isSearchPage || !searchProbe?.hasUserTab); attempt++) {
    await tobub.atoms.waitFor({ delay: [700, 1100] });
    searchProbe = await observeSearchPage();
  }
  if (!searchProbe?.isSearchPage || !searchProbe?.hasUserTab) {
    stopReason = 'search_failed';
    error = '首页搜索没有进入小红书搜索结果页；未访问主页，也未写入作品。';
    throw new Error(error);
  }

  await tobub.atoms.click({ selector: '#user', visibleOnly: true }, { timeout: 10000 });
  await tobub.atoms.waitFor({ delay: [1000, 1600] });
  searchProbe = await observeSearchPage();
  for (let attempt = 0; attempt < 3 && !searchProbe?.userTabActive; attempt++) {
    await tobub.atoms.waitFor({ delay: [500, 900] });
    searchProbe = await observeSearchPage();
  }
  if (!searchProbe?.userTabActive) {
    stopReason = 'search_failed';
    error = '已进入搜索结果，但无法打开“用户”结果页；未访问主页，也未写入作品。';
    throw new Error(error);
  }

  candidateAuthors = (searchProbe.candidates ?? []).slice(0, 15).map(candidate => ({
    id: String(candidate.id ?? ''),
    name: safeText(candidate.name),
    xiaohongshuId: safeText(candidate.xiaohongshuId),
    url: 'https://www.xiaohongshu.com/user/profile/' + encodeURIComponent(String(candidate.id ?? ''))
  })).filter(candidate => candidate.id && candidate.name);
  const foundCandidates = searchProbe.candidates ?? [];
  let targetAuthor = null;
  if (expectedAuthorId) {
    targetAuthor = foundCandidates.find(candidate => candidate.id === expectedAuthorId) ?? null;
    if (!targetAuthor) {
      stopReason = 'author_not_found';
      error = '搜索结果中没有找到提供的作者 ID；未访问主页，也未写入作品。';
      throw new Error(error);
    }
  } else {
    const numericXhsId = /^\d{6,20}$/.test(authorNameInput);
    const exactMatches = numericXhsId
      ? foundCandidates.filter(candidate => safeText(candidate.xiaohongshuId) === authorNameInput)
      : foundCandidates.filter(candidate => safeText(candidate.name) === safeText(authorNameInput));
    if (exactMatches.length === 1) {
      targetAuthor = exactMatches[0];
    } else if (exactMatches.length > 1) {
      stopReason = 'ambiguous_author';
      error = '搜索到多个同名作者；请补充作者 ID 或主页链接以精准匹配。';
      throw new Error(error);
    } else {
      stopReason = 'author_not_found';
      error = '搜索结果中没有找到名称或小红书号完全匹配的作者；请检查输入，或补充主页 ID。';
      throw new Error(error);
    }
  }

  authorId = String(targetAuthor.id);
  authorName = safeText(targetAuthor.name);
  xiaohongshuId = safeText(targetAuthor.xiaohongshuId) || (/^\d{6,20}$/.test(authorNameInput) ? authorNameInput : '');
  profileUrl = 'https://www.xiaohongshu.com/user/profile/' + encodeURIComponent(authorId);
  const clickSelector = 'a[href*="/user/profile/' + authorId + '"]';
  const prepareClickExpression = '(()=>{const a=document.querySelector(' + JSON.stringify(clickSelector) + ');if(!a)return null;a.setAttribute("target","_self");return a.href;})()';
  const preparedHref = unwrap(await tobub.atoms.evaluate({ mode: 'expression', expression: prepareClickExpression }));
  if (!preparedHref) {
    stopReason = 'author_not_found';
    error = '找到作者卡片后无法打开其主页链接；未写入作品。';
    throw new Error(error);
  }
  await tobub.atoms.click({ selector: clickSelector, visibleOnly: true }, { timeout: 10000 });
  await tobub.atoms.waitFor({ delay: [1500, 2200] });
  probe = await observePage();
  for (let attempt = 0; attempt < 2 && (!probe?.itemSelector || !probe?.cardCount); attempt++) {
    await tobub.atoms.waitFor({ delay: [900, 1400] });
    probe = await observePage();
  }
  let pageAuthorId = String(probe?.profileId ?? '');
  try { pageAuthorId = decodeURIComponent(pageAuthorId); } catch {}
  if (!probe?.pathname?.startsWith('/user/profile/') || !pageAuthorId) {
    stopReason = 'profile_mismatch';
    error = '点击用户搜索结果后没有进入可验证的作者主页；未写入作品。';
    throw new Error(error);
  }
  if (pageAuthorId !== authorId) {
    stopReason = 'profile_mismatch';
    error = '从搜索结果进入的主页 ID 与目标作者不一致，已停止以避免采集错作者。';
    throw new Error(error);
  }
  const pageXhsId = safeText(probe?.xiaohongshuId);
  if (/^\d{6,20}$/.test(authorNameInput) && pageXhsId !== authorNameInput) {
    stopReason = 'profile_mismatch';
    error = '主页显示的小红书号与输入号码不一致，已停止以避免采集错作者。';
    throw new Error(error);
  }
  if (pageXhsId) xiaohongshuId = pageXhsId;
  authorIdentityVerified = true;
  stopReason = 'scroll_limit';
  if (probe?.profileName) authorName = safeText(probe.profileName);
  await ensureAuthorRecord();
  if (!probe?.itemSelector || !probe?.cardCount) {
    if (probe?.endSignal && !probe?.loginGate) {
      terminalSeen = true;
      stopReason = 'timeline_end';
    } else if (probe?.loginGate) {
      stopReason = 'login_required';
      error = '页面要求登录；请确认 xhs Profile 的登录态后重试。';
    } else {
      stopReason = 'no_post_cards';
      error = '主页已打开，但没有识别到作品卡片；页面结构可能已变化，未写入作品记录。';
    }
  } else {
    const fields = makeFields(probe);
    if (!fields.length) throw new Error('页面中没有可用于读取作品的字段。');
    const selector = probe.itemSelector;
    const idField = probe.selectors?.idAttr ? 'id' : probe.selectors?.link ? 'link' : undefined;
    let noProgress = 0;
    for (let pass = 0; pass < maxScrollPasses && works.length < maxWorks; pass++) {
      if (pass > 0) {
        await tobub.atoms.scroll({
          mode: 'viewport',
          distance: tobub.utils.randInt(560, 960),
          steps: tobub.utils.randInt(4, 8),
          stepPauseRange: [35, 75]
        });
        scrolls++;
        await tobub.atoms.waitFor({ delay: [800, 1400] });
        probe = await observePage();
      }
      const batch = await tobub.atoms.extractList({
        itemSelector: selector,
        fields,
        ...(idField ? { idField } : {}),
        dedupe: idField ? 'field' : 'content',
        maxItems: 500,
        perItemTimeout: 2200,
        includeErrors: true,
        errorPolicy: 'skip'
      });
      const records = Array.isArray(batch?.records) ? batch.records : [];
      const reportedFailures = Number(batch?.failedCount);
      const errorListCount = Array.isArray(batch?.errors) ? batch.errors.length : 0;
      const rowErrorCount = records.reduce((count, row) => {
        if (Array.isArray(row?.errors)) return count + row.errors.length;
        return count + (row?.error ? 1 : 0);
      }, 0);
      extractionFailures += Math.max(
        Number.isFinite(reportedFailures) ? Math.max(0, reportedFailures) : 0,
        errorListCount,
        rowErrorCount
      );
      cardsSeen += records.length;
      let added = 0;
      for (const row of records) {
        if (works.length >= maxWorks) break;
        const data = { ...(row?.fields ?? {}), ...(row?.jsonFields ?? {}) };
        const link = String(data.link ?? '').trim();
        const id = String(getNoteId(link) || data.id || row?.id || '').trim();
        if (!id) {
          malformedCount++;
          continue;
        }
        if (seen.has(id)) {
          duplicateCount++;
          continue;
        }
        const url = normalizeSiteUrl(link, id);
        if (!url) {
          malformedCount++;
          continue;
        }
        seen.add(id);
        const title = safeText(data.title) || '小红书作品 ' + id;
        const coverUrl = safeText(data.cover);
        const note = {
          id,
          title,
          url,
          coverUrl,
          authorId,
          authorName,
          xiaohongshuId,
          publishedAt: safeText(data.publishedAt),
          likeCount: safeText(data.likes)
        };
        await ensureAuthorRecord();
        let contentItemId = null;
        let saved = false;
        try {
          const result = await tobub.db.saveContent({
            platform: 'xiaohongshu',
            contentType: 'note',
            externalId: id,
            ...(authorContentItemId ? { parentId: authorContentItemId } : {}),
            title,
            summary: '',
            url,
            metadata: {
              authorId,
              authorName,
              xiaohongshuId,
              publishedAt: note.publishedAt,
              likeCount: note.likeCount,
              coverUrl,
              source: 'author_profile',
              capturedAt: new Date().toISOString()
            },
            rawData: { ...data, ...note }
          });
          const resultId = Number(result?.contentItemId);
          if (Number.isInteger(resultId) && resultId > 0) {
            contentItemId = resultId;
            saved = true;
          } else {
            saveFailures++;
          }
        } catch {
          saveFailures++;
        }
        works.push({ ...note, contentItemId, saved });
        added++;
      }
      if (probe?.endSignal && added === 0) {
        terminalSeen = true;
        stopReason = 'timeline_end';
        break;
      }
      if (works.length >= maxWorks) {
        stopReason = 'max_works_limit';
        break;
      }
      if (!added) noProgress++;
      else noProgress = 0;
      if (noProgress >= 3) {
        stopReason = 'no_progress';
        break;
      }
      if (pass === maxScrollPasses - 1) stopReason = 'scroll_limit';
    }
  }
} catch (e) {
  error = safeText(e?.message ?? e).slice(0, 240) || '读取主页或保存记录失败。';
  if (!stopReason || stopReason === 'scroll_limit') stopReason = 'page_error';
}
const savedCount = works.filter(item => item.saved).length;
const complete = terminalSeen && extractionFailures === 0 && saveFailures === 0 && malformedCount === 0;
const status = complete && works.length === 0
  ? 'empty'
  : complete
    ? 'complete'
    : works.length > 0 || saveFailures > 0
      ? 'partial'
      : 'partial';
if (!error && stopReason === 'max_works_limit') {
  error = maxWorks >= 500
    ? '达到当前技能最大上限 500；本轮未确认采完。若需采集更多作品，须先提高技能上限后重跑。'
    : '达到本次设置的作品数上限；本轮未确认采完，可将上限调高至 500 后重跑。';
}
if (!error && stopReason === 'no_progress' && !terminalSeen) {
  error = '连续滚动后未发现新作品，页面没有给出明确的列表结束标记。';
}
if (extractionFailures > 0) {
  const detail = '发现 ' + extractionFailures + ' 次作品字段提取失败，结果未确认完整。';
  error = error ? error + '；' + detail : detail;
}
return {
  status,
  complete,
  stopReason,
  author: authorIdentityVerified ? {
    id: authorId,
    name: authorName,
    xiaohongshuId,
    url: profileUrl,
    contentItemId: authorContentItemId
  } : null,
  candidateAuthors,
  works,
  counts: {
    cardsSeen,
    worksFound: works.length,
    savedCount,
    duplicateCount,
    malformedCount,
    extractionFailures,
    saveFailures,
    scrolls
  },
  error
};
